import React, { useState } from "react";
import {
  TextField,
  Button,
  CircularProgress,
  Box,
  Typography,
} from "@mui/material";
import axios from "axios";

interface PostAdResponse {
  message: string; // Expected to be the base64 screenshot
}

const App: React.FC = () => {
  const [price, setPrice] = useState<string>("");
  const [description, setDescription] = useState<string>("");
  const [loading, setLoading] = useState<boolean>(false);
  const [screenshot, setScreenshot] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);

  const handleSubmit = async () => {
    setLoading(true);
    setError(null);

    try {
      const response = await axios.post<PostAdResponse>(
        "http://localhost:4000/publishAd",
        {
          price,
          description,
        }
      );

      setScreenshot(response.data.message); // Aquí esperamos recibir el base64 del screenshot
    } catch (err) {
      setError("Hubo un error al publicar el anuncio.");
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  return (
    <Box sx={{ maxWidth: 600, mx: "auto", mt: 5 }}>
      <Typography variant="h4" gutterBottom>
        Publicar Anuncio
      </Typography>

      <TextField
        fullWidth
        label="Precio"
        variant="outlined"
        margin="normal"
        value={price}
        onChange={(e) => setPrice(e.target.value)}
      />

      <TextField
        fullWidth
        label="Descripción"
        variant="outlined"
        margin="normal"
        multiline
        rows={4}
        value={description}
        onChange={(e) => setDescription(e.target.value)}
      />

      {loading ? (
        <Box display="flex" justifyContent="center" mt={2}>
          <CircularProgress />
        </Box>
      ) : (
        <Button
          fullWidth
          variant="contained"
          color="primary"
          onClick={handleSubmit}
          sx={{ mt: 2 }}
        >
          Publicar
        </Button>
      )}

      {error && (
        <Typography color="error" mt={2}>
          {error}
        </Typography>
      )}

      {screenshot && (
        <Box mt={4} textAlign="center">
          <Typography variant="h6">Anuncio Publicado:</Typography>
          <img
            src={`data:image/png;base64,${screenshot}`}
            alt="Screenshot del anuncio"
            style={{ maxWidth: "100%" }}
          />
        </Box>
      )}
    </Box>
  );
};

export default App;
